dashboard.definition:
{
  "title": "UniFi - Flow Analysis",
  "description": "NetFlow from the UniFi gateway (Splunk Stream IPFIX). Filters to real 5-tuple flows.",
  "inputs": {
    "input_time": {
      "type": "input.timerange",
      "title": "Time range",
      "options": { "token": "tr", "defaultValue": "-4h@h,now" }
    },
    "input_refresh": {
      "type": "input.dropdown",
      "title": "Auto-refresh",
      "options": {
        "token": "rfsh",
        "defaultValue": "5m",
        "items": [
          { "label": "Off", "value": "" },
          { "label": "1m", "value": "1m" },
          { "label": "5m", "value": "5m" },
          { "label": "15m", "value": "15m" }
        ]
      }
    }
  },
  "defaults": { "dataSources": { "ds.search": { "options": { "refresh": "$rfsh$", "refreshType": "delay" } } } },
  "dataSources": {
    "ds_flows": {
      "type": "ds.search",
      "options": {
        "query": "search `unifi_netflow` | stats count as flows",
        "queryParameters": { "earliest": "$tr.earliest$", "latest": "$tr.latest$" }
      },
      "name": "Flow count"
    },
    "ds_bytes": {
      "type": "ds.search",
      "options": {
        "query": "search `unifi_netflow` | stats sum(bytes_in) as bytes | eval bytes=round(bytes/1024/1024,1)",
        "queryParameters": { "earliest": "$tr.earliest$", "latest": "$tr.latest$" }
      },
      "name": "Bytes MB"
    },
    "ds_sources": {
      "type": "ds.search",
      "options": {
        "query": "search `unifi_netflow` | stats dc(src_ip) as sources",
        "queryParameters": { "earliest": "$tr.earliest$", "latest": "$tr.latest$" }
      },
      "name": "Unique sources"
    },
    "ds_dests": {
      "type": "ds.search",
      "options": {
        "query": "search `unifi_netflow` | stats dc(dest_ip) as destinations",
        "queryParameters": { "earliest": "$tr.earliest$", "latest": "$tr.latest$" }
      },
      "name": "Unique destinations"
    },
    "ds_trend": {
      "type": "ds.search",
      "options": {
        "query": "search `unifi_netflow` | timechart span=5m sum(bytes_in) as bytes sum(packets_in) as packets count as flows | eval bytes_mb=round(bytes/1024/1024,2) | fields _time bytes_mb packets flows",
        "queryParameters": { "earliest": "$tr.earliest$", "latest": "$tr.latest$" }
      },
      "name": "Traffic over time"
    },
    "ds_sankey": {
      "type": "ds.search",
      "options": {
        "query": "search `unifi_netflow` | where cidrmatch(\"10.0.0.0/8\",src_ip) OR cidrmatch(\"192.168.0.0/16\",src_ip) OR cidrmatch(\"172.16.0.0/12\",src_ip) | eval src_mac_l=lower(src_mac) | lookup unifi_client_lookup client_mac AS src_mac_l OUTPUT client_name AS src_client | join type=left src_ip [| inputlookup unifi_client_lookup | rename client_ip as src_ip client_name as src_name | dedup src_ip | table src_ip src_name] | eval source=coalesce(src_client, src_name, src_ip) | eval service=case(dest_port=443,\"https\", dest_port=80,\"http\", dest_port=53,\"dns\", dest_port=22,\"ssh\", dest_port=123,\"ntp\", dest_port=25,\"smtp\", dest_port=853,\"dot\", dest_port=993,\"imaps\", dest_port=5223,\"apns\", dest_port=3478,\"stun\", dest_port=5353,\"mdns\", dest_port=1900,\"ssdp\", dest_port=8080,\"http-alt\", dest_port<1024, tostring(dest_port), true(), \"other\") | eval dest_class=if(cidrmatch(\"10.0.0.0/8\",dest_ip) OR cidrmatch(\"192.168.0.0/16\",dest_ip) OR cidrmatch(\"172.16.0.0/12\",dest_ip),\"LAN\",\"Internet\") | eval target=service.\" (\".dest_class.\")\" | stats sum(bytes_in) as value by source, target | where isnotnull(source) AND isnotnull(target) AND value>0 | sort - value | head 25 | table source target value",
        "queryParameters": { "earliest": "$tr.earliest$", "latest": "$tr.latest$" }
      },
      "name": "Sankey client to service"
    },
    "ds_talkers": {
      "type": "ds.search",
      "options": {
        "query": "search `unifi_netflow` | eval src_mac_l=lower(src_mac) | lookup unifi_client_lookup client_mac AS src_mac_l OUTPUT client_name AS src_client | join type=left src_ip [| inputlookup unifi_client_lookup | rename client_ip as src_ip client_name as src_name | dedup src_ip | table src_ip src_name] | eval source=coalesce(src_client, src_name, src_ip) | stats sum(bytes_in) as bytes, sum(packets_in) as packets, count as flows by source src_ip | eval bytes_mb=round(bytes/1024/1024,2) | sort - bytes | head 15 | table source src_ip bytes_mb packets flows",
        "queryParameters": { "earliest": "$tr.earliest$", "latest": "$tr.latest$" }
      },
      "name": "Top talkers"
    },
    "ds_proto": {
      "type": "ds.search",
      "options": {
        "query": "search `unifi_netflow` | eval proto=case(protoid=6,\"TCP\", protoid=17,\"UDP\", protoid=1,\"ICMP\", true(), tostring(protoid)) | stats sum(bytes_in) as bytes by proto | eval bytes_mb=round(bytes/1024/1024,2) | fields proto bytes_mb",
        "queryParameters": { "earliest": "$tr.earliest$", "latest": "$tr.latest$" }
      },
      "name": "Protocol mix"
    },
    "ds_services": {
      "type": "ds.search",
      "options": {
        "query": "search `unifi_netflow` | eval proto=case(protoid=6,\"TCP\", protoid=17,\"UDP\", protoid=1,\"ICMP\", true(), tostring(protoid)) | eval service=case(dest_port=443,\"https\", dest_port=80,\"http\", dest_port=53,\"dns\", dest_port=22,\"ssh\", dest_port=123,\"ntp\", dest_port=25,\"smtp\", dest_port=853,\"dot\", dest_port=993,\"imaps\", dest_port=5223,\"apns\", dest_port=3478,\"stun\", dest_port=5353,\"mdns\", dest_port=1900,\"ssdp\", dest_port=8080,\"http-alt\", true(), tostring(dest_port)) | stats sum(bytes_in) as bytes, count as flows by proto, service, dest_port | eval bytes_mb=round(bytes/1024/1024,2) | sort - bytes | head 20 | table proto service dest_port bytes_mb flows",
        "queryParameters": { "earliest": "$tr.earliest$", "latest": "$tr.latest$" }
      },
      "name": "Top services"
    },
    "ds_destinations": {
      "type": "ds.search",
      "options": {
        "query": "search `unifi_netflow` | eval is_rfc1918=if(cidrmatch(\"10.0.0.0/8\",dest_ip) OR cidrmatch(\"192.168.0.0/16\",dest_ip) OR cidrmatch(\"172.16.0.0/12\",dest_ip),\"internal\",\"external\") | join type=left dest_ip [| inputlookup unifi_client_lookup | rename client_ip as dest_ip client_name as dest_name | dedup dest_ip | table dest_ip dest_name] | eval destination=coalesce(dest_name, dest_ip) | stats sum(bytes_in) as bytes, count as flows by destination dest_ip is_rfc1918 | eval bytes_mb=round(bytes/1024/1024,2) | sort - bytes | head 15 | table destination dest_ip is_rfc1918 bytes_mb flows",
        "queryParameters": { "earliest": "$tr.earliest$", "latest": "$tr.latest$" }
      },
      "name": "Top destinations"
    },
    "ds_conv": {
      "type": "ds.search",
      "options": {
        "query": "search `unifi_netflow` | eval proto=case(protoid=6,\"TCP\", protoid=17,\"UDP\", protoid=1,\"ICMP\", true(), tostring(protoid)) | eval src_mac_l=lower(src_mac) | lookup unifi_client_lookup client_mac AS src_mac_l OUTPUT client_name AS src_client client_mac AS mac_from_srcmac | join type=left src_ip [| inputlookup unifi_client_lookup | rename client_ip as src_ip client_name as src_name client_mac as mac_from_ip | dedup src_ip | table src_ip src_name mac_from_ip] | eval src=coalesce(src_client, src_name, src_ip), client_mac=coalesce(mac_from_srcmac, mac_from_ip) | stats sum(bytes_in) as bytes, sum(packets_in) as packets, count as flows by src src_ip dest_ip dest_port proto client_mac | eval bytes_mb=round(bytes/1024/1024,2) | sort - bytes | head 40 | table src src_ip dest_ip dest_port proto bytes_mb packets flows client_mac",
        "queryParameters": { "earliest": "$tr.earliest$", "latest": "$tr.latest$" }
      },
      "name": "Top conversations"
    },
    "ds_clients": {
      "type": "ds.search",
      "options": {
        "query": "search `unifi_netflow` | eval src_mac_l=lower(src_mac) | lookup unifi_client_lookup client_mac AS src_mac_l OUTPUT client_name AS src_client client_type AS src_type client_mac AS mac_from_srcmac | join type=left src_ip [| inputlookup unifi_client_lookup | rename client_ip as src_ip client_name as src_name client_mac as mac_from_ip client_type as src_type2 | dedup src_ip | table src_ip src_name mac_from_ip src_type2] | eval client=coalesce(src_client, src_name), client_mac=coalesce(mac_from_srcmac, mac_from_ip), client_type=coalesce(src_type, src_type2) | where isnotnull(client) AND client!=\"\" | stats sum(bytes_in) as bytes, sum(packets_in) as packets, count as flows, dc(dest_ip) as destinations by client client_mac client_type | eval bytes_mb=round(bytes/1024/1024,2) | sort - bytes | head 25 | table client client_mac client_type bytes_mb packets flows destinations",
        "queryParameters": { "earliest": "$tr.earliest$", "latest": "$tr.latest$" }
      },
      "name": "UniFi clients as talkers"
    },
    "ds_exporter": {
      "type": "ds.search",
      "options": {
        "query": "search `unifi_netflow` | stats sum(bytes_in) as bytes, sum(packets_in) as packets, count as flows, dc(src_ip) as sources, dc(dest_ip) as destinations by exporter_ip | eval bytes_mb=round(bytes/1024/1024,2) | table exporter_ip bytes_mb packets flows sources destinations",
        "queryParameters": { "earliest": "$tr.earliest$", "latest": "$tr.latest$" }
      },
      "name": "Exporters"
    }
  },
  "visualizations": {
    "viz_flows": {
      "type": "viz.singlevalue",
      "options": { "majorColor": "#1182f3", "unit": "flows", "unitPosition": "after" },
      "dataSources": { "primary": "ds_flows" },
      "title": "Flows"
    },
    "viz_bytes": {
      "type": "viz.singlevalue",
      "options": { "majorColor": "#118832", "unit": "MB", "unitPosition": "after" },
      "dataSources": { "primary": "ds_bytes" },
      "title": "Bytes in"
    },
    "viz_sources": {
      "type": "viz.singlevalue",
      "options": { "majorColor": "#9b59f3" },
      "dataSources": { "primary": "ds_sources" },
      "title": "Unique sources"
    },
    "viz_dests": {
      "type": "viz.singlevalue",
      "options": { "majorColor": "#f39c12" },
      "dataSources": { "primary": "ds_dests" },
      "title": "Unique destinations"
    },
    "viz_trend": {
      "type": "viz.area",
      "options": { "yAxisTitleText": "MB / 5m" },
      "dataSources": { "primary": "ds_trend" },
      "title": "Traffic over time (bytes MB, packets, flows)"
    },
    "viz_sankey": {
      "type": "splunk.sankey",
      "options": { "linkColorMode": "source" },
      "dataSources": { "primary": "ds_sankey" },
      "title": "Traffic flow: LAN clients \u2192 service (Internet vs LAN). Link width = bytes. Top 25."
    },
    "viz_talkers": {
      "type": "viz.bar",
      "options": {},
      "dataSources": { "primary": "ds_talkers" },
      "title": "Top talkers (UniFi client name when known)"
    },
    "viz_proto": {
      "type": "viz.pie",
      "options": {},
      "dataSources": { "primary": "ds_proto" },
      "title": "Protocol mix by bytes"
    },
    "viz_services": {
      "type": "viz.table",
      "options": { "count": 20 },
      "dataSources": { "primary": "ds_services" },
      "title": "Top destination ports / services"
    },
    "viz_destinations": {
      "type": "viz.table",
      "options": { "count": 15 },
      "dataSources": { "primary": "ds_destinations" },
      "title": "Top destinations (internal vs external)"
    },
    "viz_conv": {
      "type": "viz.table",
      "options": { "count": 25, "drilldown": "row" },
      "dataSources": { "primary": "ds_conv" },
      "title": "Top conversations (click a UniFi client row → Client Drilldown)",
      "eventHandlers": [
        {
          "type": "drilldown.linkToDashboard",
          "options": {
            "app": "unifi_app_for_splunk",
            "dashboard": "unifi_client_drilldown",
            "tokens": [ { "token": "client", "value": "row.client_mac.value" } ]
          }
        }
      ]
    },
    "viz_clients": {
      "type": "viz.table",
      "options": { "count": 20, "drilldown": "row" },
      "dataSources": { "primary": "ds_clients" },
      "title": "UniFi clients as talkers (click → Client Drilldown)",
      "eventHandlers": [
        {
          "type": "drilldown.linkToDashboard",
          "options": {
            "app": "unifi_app_for_splunk",
            "dashboard": "unifi_client_drilldown",
            "tokens": [ { "token": "client", "value": "row.client_mac.value" } ]
          }
        }
      ]
    },
    "viz_exporter": {
      "type": "viz.table",
      "options": {},
      "dataSources": { "primary": "ds_exporter" },
      "title": "NetFlow exporters"
    }
  },
  "layout": {
    "type": "grid",
    "options": { "width": 1440, "height": 1920 },
    "globalInputs": [ "input_time", "input_refresh" ],
    "structure": [
      { "item": "viz_flows", "type": "block", "position": { "x": 0, "y": 0, "w": 360, "h": 140 } },
      { "item": "viz_bytes", "type": "block", "position": { "x": 360, "y": 0, "w": 360, "h": 140 } },
      { "item": "viz_sources", "type": "block", "position": { "x": 720, "y": 0, "w": 360, "h": 140 } },
      { "item": "viz_dests", "type": "block", "position": { "x": 1080, "y": 0, "w": 360, "h": 140 } },
      { "item": "viz_trend", "type": "block", "position": { "x": 0, "y": 140, "w": 1440, "h": 260 } },
      { "item": "viz_sankey", "type": "block", "position": { "x": 0, "y": 400, "w": 1440, "h": 380 } },
      { "item": "viz_talkers", "type": "block", "position": { "x": 0, "y": 780, "w": 900, "h": 280 } },
      { "item": "viz_proto", "type": "block", "position": { "x": 900, "y": 780, "w": 540, "h": 280 } },
      { "item": "viz_services", "type": "block", "position": { "x": 0, "y": 1060, "w": 720, "h": 300 } },
      { "item": "viz_destinations", "type": "block", "position": { "x": 720, "y": 1060, "w": 720, "h": 300 } },
      { "item": "viz_conv", "type": "block", "position": { "x": 0, "y": 1360, "w": 1440, "h": 280 } },
      { "item": "viz_clients", "type": "block", "position": { "x": 0, "y": 1640, "w": 900, "h": 260 } },
      { "item": "viz_exporter", "type": "block", "position": { "x": 900, "y": 1640, "w": 540, "h": 260 } }
    ]
  }
}
